contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send and a fake blockNumberMod15 indicator
    // (since tests don't control block.number, we let the checker vary an input
    // that indicates whether block.number % 15 == 0 in the execution model).
    // The rule will quantify over that input and observable effects.
    function run(uint amount, uint blockMod15) public payable {
        require(amount <= address(this).balance, "insufficient balance");
        // Read before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // Make the call to fallback by sending value and invoking empty calldata
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values (only via public surface)
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // Interpret the external input blockMod15: treat 0 as meaning block.number % 15 == 0,
        // nonzero means not divisible. This is an abstract parameter the verifier will consider.
        bool isDiv15 = (blockMod15 == 0);

        // General rule expressed as a single assert:
        // If the call reverted then nothing is guaranteed about balances or pastBlockTime here.
        // If it didn't revert:
        //  - pastBlockTime must have been increased to > beforePast and at least >= block.timestamp (we only can observe monotonic increase via getter),
        //  - If the call sent exactly 10 ether and isDiv15 is true then contract balance must be zero (forwarded),
        //  - Otherwise the contract balance must equal beforeBal + amount.
        assert(
            reverted || (
                afterPast > beforePast
                && (
                    ((amount == 10 ether) && isDiv15) ? (afterBal == 0) : (afterBal == beforeBal + amount)
                )
            )
        );
    }

    // Allow receiving Ether if needed by the test harness
    receive() external payable {}
}

