contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // receive to accept any refunded Ether from c.transfer
    receive() external payable {}

    function run(uint callValue, uint preAdvance) public payable {
        require(address(this).balance >= callValue, "insufficient balance to forward");
        // record observables before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // perform the call to fallback by sending value
        try c.f{value: callValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule asserted: If the call succeeded then callValue must have been exactly 10 ether,
        // block.timestamp must have been > beforePast, and afterPast equals block.timestamp+1.
        // Additionally, if block.number % 15 == 0 then c's balance becomes 0 (drained to this contract),
        // otherwise c's balance increases by exactly callValue.
        assert(
            reverted == (callValue != 10 ether || !(block.timestamp > beforePast))
            && (
                reverted == false
                ==> (
                    afterPast == block.timestamp + 1
                    && (
                        (block.number % 15 == 0 && afterBalance == 0)
                        || (block.number % 15 != 0 && afterBalance == beforeBalance + callValue)
                    )
                )
            )
        );
    }

    // Solidity doesn't have an implication operator; implement a ==> b as (!a || b) inside the assert expression
    fallback() external payable {}
}

