contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Accept incoming refunds from C when it transfers its balance
    receive() external payable {}

    // params: amount must be 10 ether to match fallback requirement
    function run(uint amount) public payable {
        require(amount == 10 ether);
        // ensure this contract has enough balance to send
        require(address(this).balance >= amount);

        // Read observable state before call
        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // make the state-changing call to C.fallback by sending Ether
        try c.call{value: amount}(abi.encodeWithSignature("")) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after call
        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // General invariant to assert:
        // If call reverted, then no state change in pastBlockTime or balances occurred.
        // If call did not revert:
        //   - pastBlockTime must equal block.timestamp + 1
        //   - if block.number % 15 == 0 then contract's entire balance was transferred to this and c.balance == 0
        //   - otherwise c.balance == beforeBalance + amount and this.balance == beforeThis - amount
        assert(
            (reverted && afterTime == beforeTime && afterBalance == beforeBalance && afterThis == beforeThis)
            ||
            (!reverted
